      en: ["The facility was officially established in 1996.", "The park covers a total area of approximately 40 dunams (10 acres).", "It houses hundreds of monkeys rescued from labs and illegal trade.", "Operates as a recognized rehabilitation center for primates.", "Located within Ben Shemen Forest, the largest planted forest in Israel.", "Features a dedicated educational center for wildlife conservation."],
      es: ["El año de fundación de la instalación fue 1996.", "La superficie total del parque es de unos 40 dunams (aprox. 4 hectáreas).", "El parque alberga a cientos de monos de diferentes continentes.", "Sirve como centro oficial de rehabilitación para primates rescatados.", "Se encuentra dentro del bosque de Ben Shemen, el bosque plantado más grande de Israel.", "Incluye un centro educativo especializado en la conservación de especies."],
      pt: ["O ano de fundação da instituição foi 1996.", "A área total do parque é de cerca de 40 dunams (aprox. 4 hectares).", "O parque abriga centenas de macacos de diferentes continentes.", "Serve como centro oficial de reabilitação para primatas resgatados.", "Situa-se dentro da floresta de Ben Shemen, a maior floresta plantada de Israel.", "Inclui um centro educativo especializado na conservação de espécies."],
      fr: ["L'année de fondation de l'établissement était 1996.", "La superficie totale du parc est d'environ 40 dunams (env. 4 hectares).", "Le parc abrite des centaines de singes provenant de différents continents.", "Il sert de centre de réhabilitation officiel pour les primates sauvés.", "Il est situé dans la forêt de Ben Shemen, la plus grande forêt plantée d'Israël.", "Il comprend un centre éducatif spécialisé dans la protection des espèces."],
